def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    output = []
    i = 0
    n = len(template)

    def is_name_char(c):
        return ('A' <= c <= 'Z') or ('a' <= c <= 'z') or ('0' <= c <= '9') or c == '_'

    while i < n:
        c = template[i]
        if c == '{':
            # Escape: "{{"
            if i + 1 < n and template[i + 1] == '{':
                output.append('{')
                i += 2
                continue

            # Placeholder opening
            start = i
            j = i + 1
            if j >= n:
                raise ValueError("unclosed placeholder at position " + str(start))
            if template[j] == '}':
                raise ValueError("empty placeholder at position " + str(start))
            if not is_name_char(template[j]):
                raise ValueError("invalid placeholder at position " + str(start))

            # Collect name
            name_chars = [template[j]]
            j += 1
            while j < n and is_name_char(template[j]):
                name_chars.append(template[j])
                j += 1

            if j >= n:
                raise ValueError("unclosed placeholder at position " + str(start))
            if template[j] != '}':
                raise ValueError("invalid placeholder at position " + str(start))

            name = ''.join(name_chars)
            if name not in context:
                raise KeyError(name)
            output.append(str(context[name]))
            i = j + 1

        elif c == '}':
            # Escape: "}}"
            if i + 1 < n and template[i + 1] == '}':
                output.append('}')
                i += 2
                continue
            # Stray '}'
            raise ValueError("stray '}' at position " + str(i))

        else:
            output.append(c)
            i += 1

    return ''.join(output)

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")
    segments = path.split(".")
    if "" in segments:
        raise ValueError("empty segment")

    def descend(node, segs):
        if not segs:
            return node
        seg = segs[0]
        rest = segs[1:]
        if isinstance(node, dict):
            if seg not in node:
                raise KeyError(seg)
            return descend(node[seg], rest)
        elif isinstance(node, list):
            # Validate integer literal: optional single '-' then ASCII digits
            if seg.startswith("-"):
                digits = seg[1:]
            else:
                digits = seg
            if digits == "" or not set(digits) <= set("0123456789"):
                raise ValueError("invalid index")
            index = int(seg)
            try:
                next_node = node[index]
            except IndexError:
                raise IndexError(seg)
            return descend(next_node, rest)
        else:
            raise TypeError("cannot descend")

    return descend(data, segments)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if len(tokens) == 0:
        raise ValueError("empty expression")

    def is_literal(s):
        if not s:
            return False
        start = 0
        if s[0] == "+" or s[0] == "-":
            start = 1
        if start == len(s):
            return False
        for c in s[start:]:
            if c < "0" or c > "9":
                return False
        return True

    stack = []
    for i in range(len(tokens)):
        tok = tokens[i]
        if not isinstance(tok, str):
            raise TypeError("token {0} must be a str".format(i))
        if tok == "+" or tok == "-" or tok == "*" or tok == "/":
            if len(stack) < 2:
                raise ValueError("stack underflow at token {0}".format(i))
            right = stack.pop()
            left = stack.pop()
            if tok == "+":
                stack.append(left + right)
            elif tok == "-":
                stack.append(left - right)
            elif tok == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero at token {0}".format(i))
                q = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    q = -q
                stack.append(q)
        else:
            if not is_literal(tok):
                raise ValueError("unknown token at token {0}".format(i))
            stack.append(int(tok))

    if len(stack) != 1:
        raise ValueError("leftover operands")
    return stack[0]

def flatten_depth(nested, max_depth):
    # Validation in the exact required order
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    # Stack holds (item, depth). Top-level elements start at depth 1.
    # max_depth=0 means depth 1 > 0, so nothing is expanded (shallow copy).
    stack = [(item, 1) for item in reversed(nested)]

    while stack:
        item, depth = stack.pop()
        if isinstance(item, list) and depth <= max_depth:
            # Expand this list: push its elements in reverse order
            # so they are processed left-to-right.
            for sub in reversed(item):
                stack.append((sub, depth + 1))
        else:
            result.append(item)

    return result

def count_pulses(deltas: list[int], k: int, lo: int, hi: int) -> int:
       n = len(deltas)
       if not (1 <= lo <= hi <= n):
           raise ValueError

       # Prefix sums modulo k
       R = [0] * (n + 1)
       p = 0
       for i, d in enumerate(deltas):
           p += d
           R[i+1] = p % k

       freq = {}
       count = 0
       for j in range(1, n + 1):
           i_add = j - lo
           if i_add >= 0:
               r = R[i_add]
               freq[r] = freq.get(r, 0) + 1
           i_rem = j - hi - 1
           if i_rem >= 0:
               r = R[i_rem]
               freq[r] -= 1
               if freq[r] == 0:
                   del freq[r]
           count += freq.get(R[j], 0)

       return count

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    result = {}
    for i, row in enumerate(rows):
        # a. not a tuple or wrong length
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"row {i} is not a tuple of length 3")
        category, amount, refunded = row

        # b. category not a str, or empty str
        if not isinstance(category, str) or category == "":
            raise ValueError(f"row {i} has invalid category")

        # c. amount is a bool or not int/float
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i} has invalid amount type")

        # d. amount < 0
        if amount < 0:
            raise ValueError(f"row {i} has negative amount")

        # e. refunded not a bool
        if not isinstance(refunded, bool):
            raise TypeError(f"row {i} has invalid refunded type")

        # Update summary
        if category not in result:
            result[category] = {
                "count": 0,
                "gross": 0.0,
                "net": 0.0,
                "largest": 0.0,
            }
        summary = result[category]
        summary["count"] += 1
        amt = float(amount)
        summary["gross"] += amt
        if not refunded:
            summary["net"] += amt
        if amt > summary["largest"]:
            summary["largest"] = amt

    return result

def top_k_frequent(items, k):
    # Validation step 1: items must be a list
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    # Validation step 2: k must be an int (but not a bool)
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    # Validation step 3: k must be non-negative
    if k < 0:
        raise ValueError("k must be >= 0")
    if k == 0:
        return []

    # Count frequencies and record first occurrence index
    counts = {}
    first_index = {}
    for idx, val in enumerate(items):
        if val not in counts:
            counts[val] = 0
            first_index[val] = idx
        counts[val] += 1

    # Build a list of (value, count, first_index) for all distinct values
    distinct = []
    for val in counts:
        distinct.append((val, counts[val], first_index[val]))

    # Repeatedly select the best remaining element
    result = []
    remaining = distinct[:]  # shallow copy, items not mutated
    for _ in range(k):
        if not remaining:
            break
        best = remaining[0]
        for item in remaining[1:]:
            # Higher count wins; tie broken by smaller first_index
            if item[1] > best[1] or (item[1] == best[1] and item[2] < best[2]):
                best = item
        result.append((best[0], best[1]))
        remaining.remove(best)

    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str")
    if not text or text.isspace():
        raise ValueError("empty duration")

    i = 0
    n = len(text)
    total = 0
    found = 0

    # parse hours
    start = i
    while i < n and '0' <= text[i] <= '9':
        i += 1
    if i > start:
        if i < n and text[i] == 'h':
            total += int(text[start:i]) * 3600
            found += 1
            i += 1
        else:
            raise ValueError("malformed duration")
    elif i < n and text[i] == 'h':
        raise ValueError("malformed duration")

    # parse minutes
    start = i
    while i < n and '0' <= text[i] <= '9':
        i += 1
    if i > start:
        if i < n and text[i] == 'm':
            total += int(text[start:i]) * 60
            found += 1
            i += 1
        else:
            raise ValueError("malformed duration")
    elif i < n and text[i] == 'm':
        raise ValueError("malformed duration")

    # parse seconds
    start = i
    while i < n and '0' <= text[i] <= '9':
        i += 1
    if i > start:
        if i < n and text[i] == 's':
            total += int(text[start:i]) * 1
            found += 1
            i += 1
        else:
            raise ValueError("malformed duration")
    elif i < n and text[i] == 's':
        raise ValueError("malformed duration")

    if i != n or found == 0:
        raise ValueError("malformed duration")

    return total

def clamp_values(values, low, high):
    # 1. values must be a list
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    # 2. bounds must be numbers (and not bool)
    if (isinstance(low, bool) or isinstance(high, bool) or
            not isinstance(low, (int, float)) or
            not isinstance(high, (int, float))):
        raise TypeError("bounds must be numbers")

    # 3. low must not exceed high
    if low > high:
        raise ValueError("low must not exceed high")

    # 4. scan elements, clamp, and build a new list
    result = []
    for i, x in enumerate(values):
        if isinstance(x, bool) or not isinstance(x, (int, float)):
            raise TypeError(f"index {i}")
        if x < low:
            result.append(low)
        elif x > high:
            result.append(high)
        else:
            result.append(x)
    return result

class MergeLedger:
    def __init__(self):
        self.values = {}
        self.parent = {}
        self.size = {}
        self.comp_value = {}
        self.comp_set = {}
        self.num_components = 0
        self.merge_stack = []

    def _find(self, x):
        # assume x exists
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def add(self, x, value=0):
        if x in self.values:
            raise ValueError(f"Element {x} already exists")
        self.values[x] = value
        self.parent[x] = x
        self.size[x] = 1
        self.comp_value[x] = value
        self.comp_set[x] = {x}
        self.num_components += 1

    def merge(self, a, b):
        if a not in self.values or b not in self.values:
            raise KeyError("Unknown element")
        root_a = self._find(a)
        root_b = self._find(b)
        if root_a == root_b:
            return False
        # union by size: attach smaller to larger
        if self.size[root_a] < self.size[root_b]:
            root_a, root_b = root_b, root_a
        # now root_a is the larger (or equal) root, root_b is the smaller
        self.parent[root_b] = root_a
        self.size[root_a] += self.size[root_b]
        self.comp_value[root_a] += self.comp_value[root_b]
        self.comp_set[root_a].update(self.comp_set[root_b])
        # record merge for undo
        self.merge_stack.append((root_a, root_b, self.comp_set[root_b].copy()))
        self.num_components -= 1
        return True

    def same(self, a, b):
        if a not in self.values or b not in self.values:
            raise KeyError("Unknown element")
        return self._find(a) == self._find(b)

    def component_size(self, x):
        if x not in self.values:
            raise KeyError("Unknown element")
        root = self._find(x)
        return self.size[root]

    def component_value(self, x):
        if x not in self.values:
            raise KeyError("Unknown element")
        root = self._find(x)
        return self.comp_value[root]

    def add_value(self, x, delta):
        if x not in self.values:
            raise KeyError("Unknown element")
        root = self._find(x)
        self.values[x] += delta
        self.comp_value[root] += delta

    def components(self):
        return self.num_components

    def undo(self):
        if not self.merge_stack:
            raise RuntimeError("No merge to undo")
        new_root, old_root, old_set = self.merge_stack.pop()
        # restore old_root as a root
        for e in old_set:
            self.parent[e] = old_root
        # update component sets
        self.comp_set[new_root].difference_update(old_set)
        self.comp_set[old_root] = old_set
        # update sizes
        self.size[new_root] -= len(old_set)
        self.size[old_root] = len(old_set)
        # update component values
        old_sum = sum(self.values[e] for e in old_set)
        self.comp_value[new_root] -= old_sum
        self.comp_value[old_root] = old_sum
        self.num_components += 1

class IntervalSet:
    """A set of integers represented as half-open intervals [lo, hi), kept normalized."""

    def __init__(self):
        self._intervals = []  # sorted list of (lo, hi), disjoint and non-adjacent

    def add(self, lo: int, hi: int) -> None:
        """Cover every integer in [lo, hi). Overlapping and adjacent intervals are coalesced."""
        if lo >= hi:
            raise ValueError("lo must be less than hi")

        # Find the first interval that ends at or after lo
        start = 0
        while start < len(self._intervals) and self._intervals[start][1] < lo:
            start += 1
        # Find the first interval that starts after hi
        end = start
        while end < len(self._intervals) and self._intervals[end][0] <= hi:
            end += 1

        if start == end:
            # No overlap or touching – just insert
            self._intervals[start:end] = [(lo, hi)]
        else:
            # Merge all intervals from start to end-1 with the new one
            new_lo = min(lo, self._intervals[start][0])
            new_hi = max(hi, self._intervals[end - 1][1])
            self._intervals[start:end] = [(new_lo, new_hi)]

    def remove(self, lo: int, hi: int) -> None:
        """Uncover every integer in [lo, hi). Splits intervals as needed."""
        if lo >= hi:
            raise ValueError("lo must be less than hi")

        # Find the first interval that ends after lo
        start = 0
        while start < len(self._intervals) and self._intervals[start][1] <= lo:
            start += 1
        # Find the first interval that starts at or after hi
        end = start
        while end < len(self._intervals) and self._intervals[end][0] < hi:
            end += 1

        new_intervals = []
        for i in range(start, end):
            i_lo, i_hi = self._intervals[i]
            if i_lo < lo:
                new_intervals.append((i_lo, lo))
            if i_hi > hi:
                new_intervals.append((hi, i_hi))
        self._intervals[start:end] = new_intervals

    def contains(self, x: int) -> bool:
        """Return True if the integer x is covered."""
        lo, hi = 0, len(self._intervals)
        while lo < hi:
            mid = (lo + hi) // 2
            if self._intervals[mid][0] <= x:
                lo = mid + 1
            else:
                hi = mid
        idx = lo - 1
        return idx >= 0 and self._intervals[idx][1] > x

    def total(self) -> int:
        """Return the total number of integers covered."""
        return sum(hi - lo for lo, hi in self._intervals)

    def intervals(self) -> list:
        """Return the covered set as a sorted list of (lo, hi) tuples."""
        return list(self._intervals)

    def gaps(self, lo: int, hi: int) -> list:
        """Return the maximal uncovered sub-intervals of [lo, hi) as a sorted list."""
        if lo >= hi:
            raise ValueError("lo must be less than hi")

        gaps = []
        current = lo
        i = 0
        # Skip intervals that end before or at lo
        while i < len(self._intervals) and self._intervals[i][1] <= lo:
            i += 1
        # Process intervals that overlap [lo, hi)
        while i < len(self._intervals) and self._intervals[i][0] < hi:
            i_lo, i_hi = self._intervals[i]
            if i_lo > current:
                gaps.append((current, i_lo))
            current = max(current, i_hi)
            i += 1
        if current < hi:
            gaps.append((current, hi))
        return gaps

import heapq

class TaskScheduler:
    """
    A priority queue of unique task ids supporting reprioritization and cancellation.
    Higher priority is served first; ties are broken by original submission order (FIFO).
    """

    def __init__(self):
        # active tasks: task_id -> (priority, seq, entry_id)
        self._active = {}
        # heap entries: (-priority, seq, entry_id, task_id)
        self._heap = []
        self._seq_counter = 0
        self._entry_counter = 0

    def submit(self, task_id, priority) -> None:
        """Add a new active task. Raises ValueError if task_id is already active."""
        if task_id in self._active:
            raise ValueError(f"Task {task_id!r} is already active")
        seq = self._seq_counter
        self._seq_counter += 1
        entry_id = self._entry_counter
        self._entry_counter += 1
        self._active[task_id] = (priority, seq, entry_id)
        heapq.heappush(self._heap, (-priority, seq, entry_id, task_id))

    def reprioritize(self, task_id, priority) -> None:
        """Change an active task's priority. Raises KeyError if not active."""
        if task_id not in self._active:
            raise KeyError(f"Task {task_id!r} is not active")
        old_priority, seq, _ = self._active[task_id]
        if priority == old_priority:
            return  # no change needed
        entry_id = self._entry_counter
        self._entry_counter += 1
        self._active[task_id] = (priority, seq, entry_id)
        heapq.heappush(self._heap, (-priority, seq, entry_id, task_id))

    def cancel(self, task_id) -> None:
        """Remove an active task without serving it. Raises KeyError if not active."""
        if task_id not in self._active:
            raise KeyError(f"Task {task_id!r} is not active")
        del self._active[task_id]

    def pop(self):
        """Remove and return the highest-priority task (ties: earliest submission).
        Raises IndexError if no tasks are active."""
        while True:
            if not self._heap:
                raise IndexError("pop from empty scheduler")
            neg_priority, seq, entry_id, task_id = heapq.heappop(self._heap)
            if task_id in self._active:
                _, _, current_entry_id = self._active[task_id]
                if current_entry_id == entry_id:
                    del self._active[task_id]
                    return task_id
            # otherwise invalid entry, continue

    def peek(self):
        """Return the highest-priority task without removing it.
        Raises IndexError if no tasks are active."""
        while True:
            if not self._heap:
                raise IndexError("peek from empty scheduler")
            neg_priority, seq, entry_id, task_id = self._heap[0]
            if task_id in self._active:
                _, _, current_entry_id = self._active[task_id]
                if current_entry_id == entry_id:
                    return task_id
            # invalid entry, discard and continue
            heapq.heappop(self._heap)

    def priority_of(self, task_id) -> int:
        """Return the current priority of an active task. Raises KeyError if not active."""
        if task_id not in self._active:
            raise KeyError(f"Task {task_id!r} is not active")
        return self._active[task_id][0]

    def __len__(self) -> int:
        """Return the number of active tasks."""
        return len(self._active)

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        curr = ordered[i]
        # Overlapping delete ranges or identical start positions conflict.
        if curr[0] < prev[0] + prev[1] or curr[0] == prev[0]:
            raise ValueError("conflicting hunks")
    for start, delete, insert in ordered:
        if start < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")
    # Apply all hunks simultaneously against the original document.
    result = []
    current = 0
    for start, delete, insert in ordered:
        result.extend(lines[current:start])
        result.extend(insert)
        current = start + delete
    result.extend(lines[current:])
    return result

from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self.capacity = capacity
        # key -> (value, stored_time, ttl)
        self.data = OrderedDict()
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0

    def _purge(self, now):
        dead = [
            k for k, (v, t, ttl) in self.data.items()
            if ttl is not None and now >= t + ttl
        ]
        for k in dead:
            del self.data[k]
            self.expirations += 1

    def put(self, key, value, now, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be a positive number or None")
        self._purge(now)
        if key in self.data:
            self.data[key] = (value, now, ttl)
            self.data.move_to_end(key)
        else:
            if len(self.data) >= self.capacity:
                self.data.popitem(last=False)
                self.evictions += 1
            self.data[key] = (value, now, ttl)  # inserted at the end (MRU)

    def get(self, key, now):
        self._purge(now)
        if key in self.data:
            self.hits += 1
            self.data.move_to_end(key)
            return self.data[key][0]
        self.misses += 1
        return None

    def stats(self):
        return {
            "hits": self.hits,
            "misses": self.misses,
            "evictions": self.evictions,
            "expirations": self.expirations,
        }

    def __len__(self):
        return len(self.data)

class CountingBag:
    """A multiset (bag) of hashable items that tracks counts and reports
    its most common items with a fully specified, deterministic ordering."""

    def __init__(self):
        self._counts = {}          # item -> count (only for count > 0)
        self._entry = {}           # item -> entry sequence number (only for count > 0)
        self._next_entry = 0       # monotonic counter for entry moments
        self._total = 0            # total number of occurrences

    def add(self, item) -> int:
        """Add one occurrence of item; return the item's new count."""
        if item in self._counts:
            self._counts[item] += 1
        else:
            self._counts[item] = 1
            self._entry[item] = self._next_entry
            self._next_entry += 1
        self._total += 1
        return self._counts[item]

    def discard(self, item) -> bool:
        """Remove one occurrence; return True if removed, False if absent."""
        if item not in self._counts:
            return False
        self._counts[item] -= 1
        self._total -= 1
        if self._counts[item] == 0:
            del self._counts[item]
            del self._entry[item]
        return True

    def count(self, item) -> int:
        """Return current count (0 if absent)."""
        return self._counts.get(item, 0)

    def __len__(self) -> int:
        """Return total number of occurrences across all items."""
        return self._total

    def distinct(self) -> int:
        """Return number of distinct items currently present (count >= 1)."""
        return len(self._counts)

    def most_common(self, k) -> list:
        """Return the k items with the highest counts as (item, count) tuples,
        ordered by count descending; ties broken by earlier entry moment first.
        Only items currently present may appear. If fewer than k items are
        present, return all of them. most_common(0) returns [].
        Raise ValueError if k < 0.
        """
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        # Build list of (item, count) for all present items
        items = list(self._counts.items())
        # Sort by count descending, then entry moment ascending
        items.sort(key=lambda x: (-x[1], self._entry[x[0]]))
        return items[:k]

class UndoStack:
    """A LIFO stack of arbitrary Python values whose mutating operations can be undone."""

    def __init__(self):
        self._stack = []
        self._history = []

    def push(self, x) -> None:
        """Push x onto the top of the stack."""
        self._stack.append(x)
        self._history.append(('pop',))

    def pop(self):
        """Remove and return the top value. Raise IndexError if empty."""
        if not self._stack:
            raise IndexError("pop from empty stack")
        val = self._stack.pop()
        self._history.append(('push', val))
        return val

    def peek(self):
        """Return the top value without removing it. Raise IndexError if empty."""
        if not self._stack:
            raise IndexError("peek from empty stack")
        return self._stack[-1]

    def undo(self) -> None:
        """Reverse the most recent successful push or pop that hasn't been undone."""
        if not self._history:
            raise RuntimeError("nothing to undo")
        action = self._history.pop()
        if action[0] == 'pop':
            # Reverse a push: remove the top element
            self._stack.pop()
        else:  # 'push'
            # Reverse a pop: put the value back on top
            self._stack.append(action[1])

    def __len__(self) -> int:
        """Return the number of values currently on the stack."""
        return len(self._stack)

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, [])
        for d in ds:
            graph.setdefault(d, [])
            graph[pkg].append(d)
    order = []
    visiting = set()
    visited = set()

    def visit(node):
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        if node in visited:
            return
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)
        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        if node not in visited:
            visit(node)
    return order

def insert_booking(bookings, new):
    start, end = new
    if start >= end:
        raise ValueError("empty booking")
    result = []
    i = 0
    while i < len(bookings) and bookings[i][1] <= start:
        result.append(bookings[i])
        i += 1
    while i < len(bookings) and bookings[i][0] < end:
        start = min(start, bookings[i][0])
        end = max(end, bookings[i][1])
        i += 1
    result.append((start, end))
    result.extend(bookings[i:])
    return result

import re

def compute_balances(transactions):
    balances = {}
    # Strict pattern: one or more digits, optionally followed by a dot and 1-2 digits.
    pattern = re.compile(r'[0-9]+(\.[0-9]{1,2})?')

    for tx in transactions:
        amount_str = tx["amount"]
        if not pattern.fullmatch(amount_str):
            raise ValueError("invalid amount")

        if '.' in amount_str:
            int_part, frac_part = amount_str.split('.')
            cents = int(int_part) * 100
            if len(frac_part) == 1:
                cents += int(frac_part) * 10
            else:  # len == 2
                cents += int(frac_part)
        else:
            cents = int(amount_str) * 100

        if cents <= 0:
            raise ValueError("amount must be positive")

        sender = tx["from"]
        receiver = tx["to"]
        balances[sender] = balances.get(sender, 0) - cents
        balances[receiver] = balances.get(receiver, 0) + cents

    return balances

def purge_expired(sessions, now):
    purged = []
    for sid, expiry in list(sessions.items()):
        if expiry <= now:
            del sessions[sid]
            purged.append(sid)
    return purged

def merge_settings(defaults, overrides):
    result = dict(defaults)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_settings(result[key], value)
        else:
            result[key] = value
    return result

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

def min_cost_route(n, edges, s, t, switch_cost):
    if s == t:
        return 0
    # Compress edges
    min_edge = {}
    for u, v, w, color in edges:
        if u > v:
            u, v = v, u
        key = (u, v, color)
        if key not in min_edge or w < min_edge[key]:
            min_edge[key] = w
    # Collect colors per node
    colors_at_node = [set() for _ in range(n)]
    for (u, v, color), w in min_edge.items():
        colors_at_node[u].add(color)
        colors_at_node[v].add(color)
    # Assign state IDs
    state_id = {}
    next_id = n
    for u in range(n):
        for color in colors_at_node[u]:
            state_id[(u, color)] = next_id
            next_id += 1
    total_states = next_id
    # Build adjacency list
    adj = [[] for _ in range(total_states)]
    for (u, v, color), w in min_edge.items():
        id_u_c = state_id[(u, color)]
        id_v_c = state_id[(v, color)]
        # same color transitions
        adj[id_u_c].append((id_v_c, w))
        adj[id_v_c].append((id_u_c, w))
        # from S to state
        adj[u].append((id_v_c, w))
        adj[v].append((id_u_c, w))
    # switch edges
    for (u, color), id_u_c in state_id.items():
        adj[id_u_c].append((u, switch_cost))
    # Dijkstra
    import heapq
    dist = [float('inf')] * total_states
    dist[s] = 0
    pq = [(0, s)]
    while pq:
        d, node = heapq.heappop(pq)
        if d > dist[node]:
            continue
        for neighbor, cost in adj[node]:
            nd = d + cost
            if nd < dist[neighbor]:
                dist[neighbor] = nd
                heapq.heappush(pq, (nd, neighbor))
    # Answer
    ans = float('inf')
    for color in colors_at_node[t]:
        id_t_c = state_id[(t, color)]
        if dist[id_t_c] < ans:
            ans = dist[id_t_c]
    return ans if ans != float('inf') else -1
